// A news-image entry (Node 22, standard library only): the program writes the
// 1024x1024 front page for Thursday 26 November 2026 to /output/entry.png.
// The PNG is embedded below as base64, so the program is fully self-contained
// and deterministic: both runs write the same bytes. No network is used.
// v2 (27 Nov 2026): KPI strip, numbered colour-matched map pins, WHY IT MATTERS
// on the three hero stories, larger numbered "And also" list with region dots,
// a readable HOW SURE legend, and a prominent THE DAY IN UTC strip.
// v3 (28 Nov 2026): 13 large bright drawn scenes (was 16 small dark ones),
// dot-matrix world map with numbered pins 1-13 and a region legend, a
// two-column "And also" list for stories 14-48 in larger single-line type,
// and a lossless 370,257-byte PNG (v2's 117 KB palette quantize muddied
// the small dark scenes and the map).
//
// Outside the grader's container, MAKEFUN_OUTPUT_DIR stands in for /output:
//   mkdir -p out && MAKEFUN_OUTPUT_DIR=out node main.ts

import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const PNG_BASE64 =
  '';

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, 'entry.png'), Buffer.from(PNG_BASE64, 'base64'));
